import{_ as a,o,c as s,a2 as r}from"./chunks/framework.BSdKG9Lk.js";const m=JSON.parse('{"title":"07 — Segurança & Escala","description":"","frontmatter":{},"headers":[],"relativePath":"docs-legados/07-seguranca.md","filePath":"docs-legados/07-seguranca.md","lastUpdated":1786474711000}'),i={name:"docs-legados/07-seguranca.md"};function t(d,e,n,l,c,u){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_07-—-seguranca-escala" tabindex="-1">07 — Segurança &amp; Escala <a class="header-anchor" href="#_07-—-seguranca-escala" aria-label="Permalink to &quot;07 — Segurança &amp; Escala&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Documento original</p><p>Conteúdo integral preservado de <code>docs/07-arquitetura-de-seguranca-e-escala.md</code>. Parte da wiki para manter a rastreabilidade com a documentação histórica do projeto.</p></div><blockquote><p><strong>Status:</strong> Definição Arquitetural Homologada<br><strong>Objetivo:</strong> Estabelecer as diretrizes para isolamento de rotas (Públicas vs. Privadas), proteção do capital intelectual (Documentação) e estratégias de escalabilidade vertical e horizontal.</p></blockquote><hr><h2 id="_1-topologia-de-roteamento-e-seguranca-route-guards" tabindex="-1">1. Topologia de Roteamento e Segurança (Route Guards) <a class="header-anchor" href="#_1-topologia-de-roteamento-e-seguranca-route-guards" aria-label="Permalink to &quot;1. Topologia de Roteamento e Segurança (Route Guards)&quot;">​</a></h2><p>O sistema deve permitir acesso irrestrito (ou de baixa fricção) ao protótipo e à interface de vendas para demonstrações e uso em campo, mas deve <strong>isolar e proteger o Capital Intelectual (Documentação, Códigos-Fonte, Relatórios Estratégicos)</strong>.</p><p>Como estamos em uma Single Page Application (React/Vite), a proteção não pode ser apenas visual. Devemos adotar o padrão de <strong>Protected Routes</strong>.</p><h3 id="_1-1-separacao-de-contextos-public-vs-private" tabindex="-1">1.1. Separação de Contextos (Public vs. Private) <a class="header-anchor" href="#_1-1-separacao-de-contextos-public-vs-private" aria-label="Permalink to &quot;1.1. Separação de Contextos (Public vs. Private)&quot;">​</a></h3><p>Implementaremos o <code>react-router-dom</code> para fatiar a aplicação:</p><ul><li><strong>Rotas Públicas (App / Protótipo):</strong> <code>/</code>, <code>/dashboard</code>, <code>/pedidos</code>, <code>/catalogo</code><ul><li><strong>Acesso:</strong> Livre no estágio atual (ou protegido por um PIN simples / Local Storage, sem necessidade de Auth pesado).</li><li><strong>Indexação:</strong> Bloqueada para crawlers via <code>&lt;meta name=&quot;robots&quot; content=&quot;noindex, nofollow&quot;&gt;</code> e <code>robots.txt</code> para evitar vazamento em motores de busca durante a fase de desenvolvimento.</li></ul></li><li><strong>Rotas Privadas (Documentação / Admin):</strong> <code>/docs</code>, <code>/admin</code>, <code>/config</code><ul><li><strong>Acesso:</strong> Protegido por um Route Guard (<code>&lt;ProtectedRoute&gt;</code>).</li><li><strong>Autenticação Obrigatória:</strong> Para acessar <code>/docs</code>, o usuário (como o contratante ou devs) deverá passar por uma autenticação real.</li><li><strong>Estratégia Recomendada:</strong> Google Workspace OAuth ou Supabase Auth (Magic Link / Senha). Se ele usa Gmail/Google Workspace, o Auth do Google é a solução mais elegante e sem atritos, garantindo que apenas e-mails autorizados (ex: <code>@suaempresa.com.br</code> ou e-mails específicos) acessem os manuais.</li></ul></li></ul><h3 id="_1-2-chunking-e-code-splitting" tabindex="-1">1.2. Chunking e Code Splitting <a class="header-anchor" href="#_1-2-chunking-e-code-splitting" aria-label="Permalink to &quot;1.2. Chunking e Code Splitting&quot;">​</a></h3><p>Além de bloquear a rota, usaremos <strong>React.lazy()</strong> e <strong>Suspense</strong> no Vite. Isso significa que o código-fonte da documentação (Markdown renderizado, componentes admin, lógicas sensíveis) será empacotado em um arquivo JavaScript separado (chunk).</p><ul><li>Se o usuário não estiver autenticado, o navegador <strong>sequer fará o download</strong> desse chunk. Isso impede que usuários mal-intencionados façam engenharia reversa inspecionando os arquivos <code>.js</code> da aplicação pública.</li></ul><hr><h2 id="_2-padroes-de-escalabilidade" tabindex="-1">2. Padrões de Escalabilidade <a class="header-anchor" href="#_2-padroes-de-escalabilidade" aria-label="Permalink to &quot;2. Padrões de Escalabilidade&quot;">​</a></h2><p>O sistema foi arquitetado para suportar desde pequenas distribuidoras (15 usuários) até grandes operações (centenas de usuários e milhares de pedidos diários).</p><h3 id="_2-1-escalabilidade-horizontal-scale-out" tabindex="-1">2.1. Escalabilidade Horizontal (Scale-Out) <a class="header-anchor" href="#_2-1-escalabilidade-horizontal-scale-out" aria-label="Permalink to &quot;2.1. Escalabilidade Horizontal (Scale-Out)&quot;">​</a></h3><p>Escalar horizontalmente significa adicionar mais máquinas (nós) para distribuir a carga de trabalho.</p><ol><li><strong>Frontend Stateless e Edge CDN (Content Delivery Network):</strong><ul><li>O build do React (arquivos HTML, CSS, JS) deve ser hospedado em uma CDN (como Firebase Hosting, Vercel ou CloudFront).</li><li>Isso garante escala infinita para o frontend. Não há servidores web rodando Node.js para entregar a UI; os arquivos são estáticos e distribuídos globalmente.</li></ul></li><li><strong>Backend Middleware / Adapters Serverless:</strong><ul><li>Em vez de um servidor Node.js/Express monolítico 24/7, os Adapters ERP (que enviam pedidos para SAP/TOTVS) devem rodar em <strong>Cloud Functions / Edge Functions</strong> (Supabase Edge Functions ou GCP Cloud Run).</li><li>Se 1.000 vendedores sincronizarem pedidos às 18h00, a infraestrutura fará o <em>auto-scaling</em> (spin-up) de 100 instâncias instantaneamente e, às 18h10, voltará a zero (scale-to-zero), otimizando custos e garantindo disponibilidade.</li></ul></li><li><strong>Connection Pooling no Banco de Dados:</strong><ul><li>Para evitar o esgotamento das conexões do PostgreSQL quando milhares de Edge Functions tentarem inserir pedidos simultaneamente, utilizaremos um gerenciador de conexões nativo (PgBouncer) configurado no Supabase.</li></ul></li></ol><h3 id="_2-2-escalabilidade-vertical-scale-up" tabindex="-1">2.2. Escalabilidade Vertical (Scale-Up) <a class="header-anchor" href="#_2-2-escalabilidade-vertical-scale-up" aria-label="Permalink to &quot;2.2. Escalabilidade Vertical (Scale-Up)&quot;">​</a></h3><p>Escalar verticalmente significa aumentar o poder (CPU, RAM, IOPS) da máquina existente.</p><ol><li><strong>Motor de Banco de Dados (PostgreSQL):</strong><ul><li>A camada de persistência em nuvem (Supabase/Cloud SQL) possui limites físicos de processamento, especialmente ao gerar relatórios OLAP ou buscas complexas em milhões de registros.</li><li>Quando a operação ultrapassar o limite da instância intermediária (ex: 4GB RAM), o PostgreSQL escala verticalmente (para 8GB, 16GB, etc.) sem necessidade de refatoração do código.</li></ul></li><li><strong>Índices e Otimização Estrutural:</strong><ul><li>Para adiar ao máximo a necessidade de escalabilidade vertical (que é mais cara), os scripts DDL já incluem indexação prévia (B-Tree) nos campos mais críticos (<code>codigo_pedido</code>, <code>vendedor_id</code>, <code>cpf_cnpj</code>), garantindo queries em milissegundos mesmo com gigabytes de dados.</li></ul></li></ol><hr><h2 id="_3-diretrizes-para-os-desenvolvedores-agentes-e-humanos" tabindex="-1">3. Diretrizes para os Desenvolvedores (Agentes e Humanos) <a class="header-anchor" href="#_3-diretrizes-para-os-desenvolvedores-agentes-e-humanos" aria-label="Permalink to &quot;3. Diretrizes para os Desenvolvedores (Agentes e Humanos)&quot;">​</a></h2><ol><li><strong>Proteja Rotas Sensíveis:</strong> Nunca importe componentes internos de documentação ou de arquitetura diretamente no <code>App.tsx</code> global sem passar por um <code>React.lazy()</code> e um <code>RouteGuard</code>.</li><li><strong>Evite Vazamento de Estado:</strong> Não carregue dados confidenciais (chaves de API, senhas, dados de configuração de ERP) em variáveis de ambiente expostas ao prefixo <code>VITE_</code>.</li><li><strong>Use JWT para APIs:</strong> Toda requisição entre a PWA e o Middleware/Supabase deve enviar um cabeçalho <code>Authorization: Bearer &lt;token&gt;</code> para validar a sessão antes de realizar qualquer operação I/O.</li></ol>',25)])])}const g=a(i,[["render",t]]);export{m as __pageData,g as default};
